<?php
if(current_user()['role']!=='Admin')throw new Exception('Admin access required.');$date=$_GET['close_date']??date('Y-m-d');echo '<div class="page-head"><div><h1>Inventory Day Closing</h1><p>The summary shows dated balances through the selected cutoff. Each close/reopen is retained as a permanent version in Reports > Daily Closing Records. Close a reviewed cutoff to prevent backdated inventory posting. Admin can reopen it with a recorded reason.</p></div></div><div class="card"><form method="get" class="inline-form"><input type="hidden" name="page" value="day_closing"><label>Cutoff Date<input type="date" name="close_date" value="'.e($date).'" required></label><button class="btn secondary">Review Cutoff</button></form></div>';
try{$s=day_summary($date);echo '<div class="card"><h3>Closing Summary</h3><table class="table"><tr><th>Sellable On Hand</th><th>Non-Sellable</th><th>Total Physical</th><th>Pending Reviews</th><th>Negative Platform Balances</th><th>Open Exceptions</th></tr><tr>';foreach(['sellable','non_sellable','physical','pending','negative_platforms','open_exceptions'] as $k)echo '<td>'.(int)$s[$k].'</td>';echo '</tr></table><p>Negative stock is retained and must be acknowledged in the closing remarks; it is never silently zeroed.</p><form method="post" action="actions.php" class="stack" data-confirm="Close inventory through this cutoff? Earlier dated stock posting will be blocked until an Admin reopens it."><input type="hidden" name="action" value="day_close"><input type="hidden" name="return" value="day_closing"><input type="hidden" name="close_date" value="'.e($date).'"><input type="hidden" name="digest" value="'.hash('sha256',json_encode($s)).'"><label>Remarks<textarea name="reason" minlength="3" required></textarea></label><label><input type="checkbox" name="review_ack" value="1" required> I reviewed all balances, pending work and stock exceptions.</label><button class="btn primary" '.($s['pending']?'disabled':'').'>Close Cutoff</button></form></div>';}catch(Throwable $e){echo '<div class="alert danger">'.e(safe_error_message($e)).'</div>';}
echo '<div class="card table-wrap"><table class="table"><tr><th>Cutoff</th><th>Status</th><th>Admin / Time</th><th>Remarks</th><th>Reopen</th></tr>';foreach(db()->query('SELECT c.*,u.name FROM day_closings c LEFT JOIN users u ON u.id=c.closed_by ORDER BY close_date DESC LIMIT 100') as $r){echo '<tr><td>'.e($r['close_date']).'</td><td>'.e($r['status']).'</td><td>'.e($r['name']).'<br>'.e($r['closed_at']).'</td><td>'.e($r['reason']).'</td><td>';if($r['status']==='Closed')echo '<form method="post" action="actions.php" data-confirm="Reopen this cutoff for corrections? The reason will be recorded."><input type="hidden" name="action" value="day_reopen"><input type="hidden" name="return" value="day_closing"><input type="hidden" name="close_date" value="'.e($r['close_date']).'"><input name="reason" placeholder="Required reason" minlength="3" required><button class="btn secondary">Reopen</button></form>';echo '</td></tr>';}echo '</table></div>';
